from mzn_bench.analysis.collect import read_csv
import matplotlib.pyplot as plt  
import pandas as pd 
import numpy as np

# Read CSVs generated by mzn-bench collect-result as pandas dataframes

_, stats = read_csv("dummy.csv", "statistics.csv")

stats = stats[stats['status'] != "ERROR"]
# print(len(stats))

stats['id'] = stats['model'] + stats['data_file']
# Get times for both configurations along with benchmark name to align them
without_proof = stats[stats.configuration.eq("Huub")][["id", "time"]].rename(columns={"time": "time_without"})
with_proof = stats[stats.configuration.eq("Huub_Proof")][["id", "time", "proof_size", "status"]].rename(columns={"time": "time_with"})

# Merge them based on the benchmark
merged = pd.merge(without_proof, with_proof, on="id")
print(f"{len(merged)} non-error instances in total")
# Filter rows where both times are less than 3
filtered = merged[(merged.time_without < 300) & (merged.time_with < 300)]
print(f"{len(filtered)} that didn't time out")

proof_timed_out = merged[(merged.time_without < 300) & (merged.time_with >= 300)]

filtered.to_csv("overheads.csv")
# Plot the results
# Plot the results
fig, ax = plt.subplots()

min_time = filtered.time_without.min()
max_time = filtered.time_without.max()

ax.plot([min_time, max_time],
        [min_time, max_time],
        color='gray', linestyle='--', linewidth=1, label='0% overhead')

ax.scatter(filtered.time_without, filtered.time_with, s=10) 

ax.set_xlabel("Time without proof logging (s)")
ax.set_ylabel("Time with proof logging (s)")
ax.set_title(f"Proof Logging Comparison ({len(filtered)} instances)")
ax.legend()
plt.savefig("comparison.png", dpi=300)


additional_time = filtered.time_with - filtered.time_without

# Plot: time_without vs. additional_time
fig, ax = plt.subplots()

overheads = [0.05, 0.1, 0.2, 0.3, 0.7]
norm = plt.Normalize(-1, 1)
cmap = plt.get_cmap('turbo')

for overhead in overheads:
    color = cmap(norm(overhead))
    ax.plot(
        [min_time, max_time],
        [overhead * min_time, overhead * max_time],
        color=color,
        linestyle='--',
        linewidth=1,
        label="{:0.0f}%  overhead".format(overhead*100),
        zorder=1
    )

ax.scatter(filtered.time_without, additional_time, s=8, color='blue', zorder=2)

# if len(proof_timed_out) > 0:
#         ax.scatter(proof_timed_out.time_without, proof_timed_out.time_with - proof_timed_out.time_without, s=10, marker='x', color='red', label="Timed out with proof logging.") 

ax.legend()
ax.set_xlabel("Time without proof logging (s)")
ax.set_ylabel("How much longer with proof logging (s)")
ax.set_title(f"Proof Logging Overhead ({len(filtered)} instances)")
plt.savefig("overheads.png", dpi=300)


# Plot: time_without vs. additional_time
fig, ax = plt.subplots()

filtered.loc[filtered["proof_size"].notnull(), "proof_size"] /= 1024
ax.scatter(filtered.time_without, filtered.proof_size, s=10) 

x = filtered.time_without
y = filtered.proof_size
mask = x.notnull() & y.notnull()  # Only use non-NaN data
coef = np.polyfit(x[mask], y[mask], deg=1)  # Linear fit (degree 1)
poly1d_fn = np.poly1d(coef)

# Plot the fitted line
x_fit = np.linspace(x.min(), x.max(), 100)
ax.plot(x_fit, poly1d_fn(x_fit), color="red", linestyle="--", label=f"Fit: ~{(coef[0] * 1024):0.1f} MB/s")


ax.set_xlabel("Time without proof logging (s)")
ax.set_ylabel("Proof Size (GB)")
ax.set_title(f"Proof File Size ({len(filtered)} instances)")
ax.legend()
plt.savefig("proof_size.png", dpi=300)